final class View {
  private static function e(mixed $v):string{return htmlspecialchars(is_scalar($v)?(string)$v:'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
  private static function money(?int $n):string{if($n===null)return 'Nog niet vastgelegd';$sign=$n<0?'-':'';$n=abs($n);return $sign.'€ '.number_format(intdiv($n,100),0,',','.').','.sprintf('%02d',$n%100);}
  private static function decimal(?int $n):string{return $n===null?'':intdiv($n,100).'.'.sprintf('%02d',$n%100);}
  private static function date(?string $v):string{return $v?(new \DateTimeImmutable($v))->format('d-m-Y'):'Nog niet vastgelegd';}
  private static function start(string $action,array $r,string $csrf,array $values=[]):string{$h='<form class="pw-form" method="post" action="/office-test/projecten/beheer"><input type="hidden" name="project_id" value="'.(int)$r['project_id'].'"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><input type="hidden" name="action" value="'.$action.'">';foreach($values as $k=>$v)$h.='<input type="hidden" name="'.self::e($k).'" value="'.self::e($v).'">';return $h;}
  private static function input(string $name,string $label,mixed $value='',string $type='text',bool $required=true):string{return '<label>'.self::e($label).'<input name="'.$name.'" type="'.$type.'" value="'.self::e($value).'"'.($required?' required':'').'></label>';}
  private static function end(string $label):string{return '<label class="pw-check"><input type="checkbox" name="confirmed" value="yes" required> Invoer en bron gecontroleerd</label><button>'.$label.'</button></form>';}
  private static function panel(string $title,string $content):string{return '<section class="pw-panel"><h3>'.$title.'</h3>'.$content.'</section>';}
  private static function bar(string $label,?int $units,string $tone):string{$text=$units===null?'Nog niet vastgelegd':number_format($units/100,1,',','.').'%';return '<div class="pw-bar-row"><span>'.$label.'</span><strong>'.$text.'</strong><div class="pw-track"><span style="width:'.($units===null?0:max(0,min(100,$units/100))).'%;background:'.$tone.'"></span></div></div>';}
  public static function overview(array $r):string{
