    foreach($cards as [$label,$value,$note,$tone])$h.='<article class="pw-kpi pw-'.$tone.'"><span>'.$label.'</span><strong>'.$e($value).'</strong><small>'.$e($note).'</small></article>';$h.='</div><div class="pw-grid">';
    $content=self::bar('Gepland volgens mijlpalen',$r['planned_percent_units'],'#9baac1').self::bar('Gemeten uitvoering',$actual?(int)$actual['percent_units']:null,'#218a89');if($actual){$content.='<p>'.$e($actual['evidence_reference']).'</p>';if($actual['basis']==='dwellings'){$content.='<p>'.(int)$actual['completed_units'].' van '.(int)$actual['total_units'].' woningen volgens de meting.</p>';if($r['target']!==(int)$actual['total_units'])$content.='<p class="pw-alert">Het projectdoel is sinds deze meting gewijzigd; controleer de grondslag.</p>';}}$content.='<a href="'.$base.'&amp;tab=uitvoering">Voortgang bijwerken ↗</a>';$h.=self::panel('Planning versus realisatie',$content);
    $p=$r['planned_seconds'];$a=$r['approved_seconds'];$max=max(1,$p??0,$a??0);$content='<p>Geplande diensten tot en met de peildatum tegenover goedgekeurde OnSite-uren.</p>';foreach([['Gepland',$p,'#9baac1'],['Goedgekeurd',$a,'#8660b1']] as [$label,$n,$color])$content.='<div class="pw-bar-row"><span>'.$label.'</span><strong>'.($n===null?'Bron niet beschikbaar':number_format($n/3600,2,',','.').' uur').'</strong><div class="pw-track"><span style="width:'.($n===null?0:100*$n/$max).'%;background:'.$color.'"></span></div></div>';$content.='<a href="'.$base.'&amp;tab=arbeid">Arbeid en uren bekijken ↗</a>';$h.=self::panel('Personeelsuren',$content);
    $content='';$roles=['contracting_party'=>'Opdrachtgever','ordering_party'=>'Opdrachtverstrekker','communication_contact'=>'Communicatie via','invoice_debtor'=>'Factuurdebiteur'];foreach($r['clients']??[] as $client){$content.='<div class="pw-client"><small>'.$roles[$client['party_role']].'</small><h4>'.$e($client['legal_name']?:$client['display_name']).'</h4><p>'.$e($client['street']).'<br>'.$e(trim($client['postal_code'].' '.$client['city'])).'</p>';foreach($client['contacts'] as $contact)$content.='<p>'.$e(trim($contact['given_name'].' '.$contact['family_name'])).((int)$contact['is_primary']===1?' · primair':'').'<br>'.$e($contact['email']).'</p>';$content.='</div>';}
    if($content==='')$content='<p>Koppel de opdrachtgever of communicatiepartij bij Werkvoorbereiding. De factuurdebiteur blijft een afzonderlijke rol.</p>';$h.=self::panel('Opdrachtgever & contacten',$content);
    $content=!empty($settings['scope_note'])?'<p class="pw-text">'.$e($settings['scope_note']).'</p>':'<p>De uitvoeringsscope is nog niet beschreven. Leg deze vast bij Werkvoorbereiding; de geaccepteerde overeenkomst blijft het contractuele brondocument.</p>';$content.='<p>Projectdoel: '.($r['target']===null?'niet vastgelegd':(int)$r['target'].' woningen').'. Gebouwen: '.($r['buildings']===null?'bron niet beschikbaar':count($r['buildings'])).'.</p>';
    if($r['housing']!==null){$assigned=array_sum(array_map(static fn($v)=>(int)$v['dwelling_count'],$r['housing']));$content.='<p>Woningtypen ingedeeld: '.$assigned.($r['target']===null?'':' van '.(int)$r['target']).'. Deze verdeling is geen uitvoeringsvoortgang.</p>';}$content.='<a href="'.$base.'&amp;tab=gebouwen">Gebouwen en woningtypen ↗</a>';$h.=self::panel('Projectscope',$content);
    $content='<dl><dt>Geplande start</dt><dd>'.self::date($settings['planned_start']??null).'</dd><dt>Geplande oplevering</dt><dd>'.self::date($settings['planned_end']??null).'</dd></dl>';foreach($r['milestones'] as $m)if((int)$m['archived']===0)$content.='<p><span class="pw-badge '.($m['actual_date']?'pw-green':($m['planned_date']<$r['today']?'pw-red':'pw-blue')).'">'.($m['actual_date']?'Gereed':($m['planned_date']<$r['today']?'Te laat':'Gepland')).'</span> '.$e($m['title']).' · '.self::date($m['planned_date']).'</p>';$content.='<a href="'.$base.'&amp;tab=uitvoering">Mijlpalen beheren ↗</a>';$h.=self::panel('Mijlpalen',$content);
    $attention=[];if($r['target']!==null&&$r['housing']!==null&&array_sum(array_column($r['housing'],'dwelling_count'))!==$r['target'])$attention[]='De woningverdeling sluit nog niet aan op het vastgelegde projectdoel.';if($r['overdue_days']!==null)$attention[]='Een of meer open mijlpalen zijn over de geplande datum.';if(!$actual)$attention[]='De uitvoeringsvoortgang is nog niet gemeten.';if(!$r['clients'])$attention[]='De opdrachtgever of contactkoppeling is nog niet vastgelegd.';if(!$settings||empty($settings['planned_start'])||empty($settings['planned_end']))$attention[]='De projectplanning heeft nog geen volledige start- en opleverdatum.';if($f&&$f['forecast_result_cents']===null)$attention[]='De financiële resultaatprognose heeft nog geen volledige grondslag.';$content=$attention?'<ul>':'<p>Geen aandachtspunten in de aangesloten projectgegevens.</p>';foreach($attention as $note)$content.='<li>'.$e($note).'</li>';if($attention)$content.='</ul>';$content.='<div class="pw-actions"><a href="/office-test/documenten?project_id='.$id.'">Projectdocumenten</a><a href="/office-test/documenten/nieuw?project_id='.$id.'">Nieuw document</a></div>';
