  public static function preparation(array $r,string $csrf,array $post=[]):string{
    if(!$r['can_manage'])return '';$e=self::e(...);$s=($post['action']??'')==='settings'?$post:($r['settings']??[]);$h='<div class="pw">'.self::panel('Projectplanning en uitvoeringsscope',self::start('settings',$r,$csrf,['revision'=>$r['settings']['revision']??0]).self::input('planned_start','Geplande start',$s['planned_start']??'','date',false).self::input('planned_end','Geplande oplevering',$s['planned_end']??'','date',false).self::input('actual_start','Werkelijke start',$s['actual_start']??'','date',false).self::input('actual_end','Werkelijke oplevering',$s['actual_end']??'','date',false).'<label>Uitvoeringsscope / projectnotitie<textarea name="scope_note" maxlength="5000" rows="5">'.$e($s['scope_note']??'').'</textarea></label><p>Deze notitie wijzigt geen contract of CRM-bron.</p>'.self::end('Projectgegevens opslaan'));
    if($r['relations']){$content='';foreach(['contracting_party'=>'Opdrachtgever','communication_contact'=>'Communicatiepartij'] as $role=>$label){$source=$r['party_sources'][$role]??[];$chosen=count($source)===1?(int)$source[0]['relation_id']:0;$content.=self::start('party',$r,$csrf,['role'=>$role,'source_hash'=>hash('sha256',json_encode($source,JSON_THROW_ON_ERROR))]).'<label>'.$label.'<select name="relation_id" required><option value="">Kies relatie</option>';foreach($r['relations'] as $relation)$content.='<option value="'.(int)$relation['id'].'"'.((int)$relation['id']===$chosen?' selected':'').'>'.$e($relation['display_name']).'</option>';$content.='</select></label>'.self::end($label.' koppelen');}$h.=self::panel('Klant- en contactkoppeling',$content.'<p>Actieve CRM-contactpersonen worden bij de gekoppelde relatie weergegeven. Factuurdebiteuren worden afzonderlijk beheerd in Finance.</p>');}
    return $h.'</div>';
  }
  private static function milestoneForm(array $r,string $csrf,array $m,array $post=[]):string{
    $e=self::e(...);$p=($post['action']??'')==='milestone'&&(int)($post['id']??0)===(int)($m['id']??0)?$post:$m;$h=self::start('milestone',$r,$csrf,['id'=>$m['id']??0,'revision'=>$m['revision']??0,'command_key'=>bin2hex(random_bytes(16))]);$h.=self::input('title','Mijlpaal',$p['title']??'').self::input('planned_date','Geplande datum',$p['planned_date']??'','date').self::input('actual_date','Werkelijk voltooid op',$p['actual_date']??'','date',false).self::input('target_percent','Geplande uitvoeringsvoortgang op deze datum (%)',$p['target_percent']??self::decimal(isset($p['target_units'])?(int)$p['target_units']:null),'text',false);return $h.self::end(isset($m['id'])?'Mijlpaal opslaan':'Mijlpaal toevoegen');
