  public static function execution(array $r,string $csrf,array $post=[]):string{
    $e=self::e(...);$id=(int)$r['project_id'];$h='<div class="pw">';$content='<p><a href="/office-test/projecten?view=inzet&amp;tab=planning&amp;shift_project='.$id.'">Personeelsplanning openen ↗</a> · <a href="/office-test/inzet/projectkaart?id='.$id.'">Projectkaart en OnSite ↗</a></p>';
    if($r['team']===null)$content.='<p>De teambron is niet beschikbaar.</p>';elseif(!$r['team'])$content.='<p>Nog geen medewerkers gekoppeld. Beheer het projectteam via Inzet.</p>';else{$content.='<div class="pw-scroll"><table><thead><tr><th>Medewerker</th><th>Rol</th><th>Status</th></tr></thead><tbody>';foreach($r['team'] as $person)$content.='<tr><td>'.$e($person['display_name']).'</td><td>'.$e($person['role_label']?:'Niet vastgelegd').'</td><td>'.((int)$person['active']===1?'Actief':'Inactief').'</td></tr>';$content.='</tbody></table></div>';}$h.=self::panel('Projectteam en inzet',$content);
    $content='';foreach($r['milestones'] as $m){if((int)$m['archived']===1)continue;$content.='<details><summary>'.$e($m['title']).' · '.self::date($m['planned_date']).' · '.($m['actual_date']?'Gereed':'Open').'</summary>';if($r['can_manage'])$content.=self::milestoneForm($r,$csrf,$m,$post).self::start('archive',$r,$csrf,['id'=>$m['id'],'revision'=>$m['revision']]).self::input('reason','Reden vervallen').self::end('Mijlpaal laten vervallen');$content.='</details>';}
    if($r['can_manage'])$content.='<details'.(($post['action']??'')==='milestone'?' open':'').'><summary>Mijlpaal toevoegen</summary>'.self::milestoneForm($r,$csrf,[],$post).'</details>';$h.=self::panel('Mijlpalen en planning',$content?:'<p>Nog geen mijlpalen vastgelegd.</p>');
    $content='<p>Voer een werkelijke meting met bronverwijzing in. Woningtypeverdeling en verstreken tijd worden niet als uitvoeringsvoortgang gebruikt.</p>';if($r['can_manage']){$p=($post['action']??'')==='measure'?$post:[];$basis=$p['basis']??'percent';$content.=self::start('measure',$r,$csrf,['latest_id'=>$r['progress'][0]['id']??0,'command_key'=>bin2hex(random_bytes(16))]).self::input('measured_date','Meetdatum',$p['measured_date']??$r['today'],'date').'<label>Meetgrondslag<select name="basis"><option value="percent"'.($basis==='percent'?' selected':'').'>Gemeten percentage</option>'.($r['target']!==null?'<option value="dwellings"'.($basis==='dwellings'?' selected':'').'>Gereedgemelde woningen / vastgelegd projectdoel</option>':'').'</select></label>'.self::input('percent','Gemeten percentage (alleen bij percentage)',$p['percent']??'','text',false);if($r['target']!==null)$content.=self::input('completed_units','Gereedgemelde woningen (alleen bij woningen)',$p['completed_units']??'','number',false);$content.=self::input('evidence_reference','Bron / onderbouwing',$p['evidence_reference']??'').self::end('Voortgang vastleggen');}
    if($r['progress']){$content.='<div class="pw-scroll"><table><thead><tr><th>Datum</th><th>Gemeten</th><th>Grondslag</th><th>Bron</th></tr></thead><tbody>';foreach(array_slice($r['progress'],0,50) as $p)$content.='<tr><td>'.self::date($p['measured_date']).'</td><td>'.number_format((int)$p['percent_units']/100,2,',','.').'%</td><td>'.$e($p['basis']==='dwellings'?$p['completed_units'].' / '.$p['total_units'].' woningen':'Percentage').'</td><td>'.$e($p['evidence_reference']).'</td></tr>';$content.='</tbody></table></div>';}$h.=self::panel('Voortgangsmetingen',$content);return $h.'</div>';
  }
  public static function financial(array $r,string $csrf,array $post=[]):string{
    if(!$r['finance_allowed'])return '<p>Financiële gegevens vereisen afzonderlijke Finance-toegang.</p>';$e=self::e(...);$f=$r['finance'];$id=(int)$r['project_id'];$content='<dl><dt>Oorspronkelijke contractsom (EUR)</dt><dd>'.self::money($f['original_cents']).'</dd><dt>Vrijgegeven contractsom (EUR)</dt><dd>'.self::money($f['accepted_base_cents']).'</dd><dt>Goedgekeurd meerwerk</dt><dd>'.self::money($f['approved_more_cents']).'</dd><dt>Goedgekeurd minderwerk</dt><dd>'.self::money($f['approved_less_cents']).'</dd><dt>Geboekte kosten tot peildatum</dt><dd>'.self::money($f['costs_cents']).'</dd><dt>Prognose eindresultaat</dt><dd>'.self::money($f['forecast_result_cents']).'</dd></dl><p>Bedragen exclusief btw. Meer-/minderwerk blijft afzonderlijk; de oorspronkelijke contractwaarde wordt niet aangepast.</p><p><a href="/office-test/finance?project_id='.$id.'">Finance van dit project ↗</a></p>';$h='<div class="pw">'.self::panel('Contract, kosten en prognose',$content);
    if($r['can_manage']&&$r['finance_write']){$p=($post['action']??'')==='forecast'?$post:[];$old=$r['forecast']??[];$form=self::start('forecast',$r,$csrf,['revision'=>$old['revision']??0]).'<p>Voer de volledige verwachte eindkosten in, inclusief de reeds geboekte kosten. Alle onderdelen moeten expliciet worden ingevuld; dit boekt geen kosten en wijzigt geen contract.</p>';foreach(['direct'=>'Directe kosten totaal excl. btw','labor'=>'Arbeid totaal','overhead'=>'Toegerekende overhead totaal excl. btw'] as $key=>$label)$form.=self::input($key,$label,$p[$key]??self::decimal(isset($old[$key.'_cents'])?(int)$old[$key.'_cents']:null));$form.=self::input('as_of','Prognosestand',$p['as_of']??($old['as_of']??$r['today']),'date').self::input('evidence_reference','Onderbouwing',$p['evidence_reference']??($old['evidence_reference']??'')).self::end('Eindkostenprognose vastleggen');$h.=self::panel('Eindkostenprognose',$form);}
    if($f['sales']!==null){$content='<div class="pw-scroll"><table><thead><tr><th>Factuur</th><th>Vervaldatum</th><th>Totaal incl. btw</th><th>Ontvangen</th><th>Status</th></tr></thead><tbody>';foreach($f['sales'] as $invoice){$issued=$invoice['status']!=='draft'&&!empty($invoice['invoice_number']);$content.='<tr><td><a href="/office-test/finance/verkoop?id='.(int)$invoice['id'].'">'.$e($invoice['invoice_number']?:'Concept #'.$invoice['id']).'</a></td><td>'.self::date($invoice['due_date']).'</td><td>'.self::money((int)$invoice['gross_cents']).'</td><td>'.self::money((int)$invoice['paid_cents']).'</td><td>'.$e($issued?((int)$invoice['paid_cents']===(int)$invoice['gross_cents']?'Betaald':$invoice['status']):($invoice['status']==='draft'?'Concept':'Verzenduitkomst controleren')).'</td></tr>';}$content.='</tbody></table></div><p><a href="/office-test/finance/verkoop?terms=1">Verkoopfactuur uit termijn maken ↗</a></p>';$h.=self::panel('Projectfacturen en ontvangsten',$content);}
    return $h.'</div>';
  }
  public static function styles():string{return '<style>.pw{color:#21364b;font-size:14px}.pw-head{margin:18px 0 24px}.pw-head>span{color:#75879b;font-size:11px;letter-spacing:.07em}.pw-head h2{margin:7px 0;font-size:26px}.pw-head p,.pw small{color:#6e8197}.pw-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.pw-kpi{background:#fff;border:1px solid #dde5ee;border-top:3px solid var(--pw-color);border-radius:12px;padding:21px}.pw-gray{--pw-color:#66768b}.pw-blue{--pw-color:#2876db}.pw-teal{--pw-color:#218a89}.pw-green{--pw-color:#23866b}.pw-red{--pw-color:#bd4e59}.pw-amber{--pw-color:#b47b24}.pw-kpi>span{font-size:12px;color:#657b93}.pw-kpi strong{display:block;font-size:26px;line-height:1.2;margin:13px 0;color:var(--pw-color);overflow-wrap:anywhere}.pw-kpi small{font-size:11px;line-height:1.6;display:block}.pw-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pw .pw-panel{padding:23px;background:#fff;border:1px solid #dde5ee;border-radius:12px;margin:0 0 18px;min-width:0}.pw-panel h3{font-size:18px;margin:0 0 18px}.pw-panel h4{margin:7px 0}.pw-panel p,.pw-panel li{line-height:1.7}.pw-panel a{color:#2166a4}.pw-panel dl{display:grid;grid-template-columns:1fr 1fr;gap:9px 18px}.pw-panel dt{font-weight:600}.pw-panel dd{margin:0}.pw-bar-row{display:grid;grid-template-columns:1fr auto;gap:8px;margin:17px 0;font-size:12px;color:#657b93}.pw-bar-row strong{color:#253f5b}.pw-track{grid-column:1/-1;height:13px;border-radius:8px;background:#eef2f7;overflow:hidden}.pw-track>span{display:block;height:100%;border-radius:8px}.pw-client{padding:10px 0;border-bottom:1px solid #e8edf3}.pw-badge{display:inline-block;padding:4px 8px;border-radius:20px;background:#eef3f8;color:var(--pw-color);font-size:11px;font-weight:700}.pw-actions{display:flex;gap:20px;flex-wrap:wrap;margin-top:20px}.pw-text{white-space:pre-wrap}.pw-alert{background:#fff4dd;padding:12px;border-radius:7px}.pw-form{display:grid;gap:13px;max-width:640px;margin:18px 0 25px}.pw-form label{display:grid;gap:6px}.pw-form input,.pw-form select,.pw-form textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd7e3;border-radius:5px;background:#fff;font:inherit}.pw-form input[type=checkbox]{width:auto}.pw-form .pw-check{display:flex;align-items:center;gap:10px;font-size:12px}.pw-form button{border:0;border-radius:6px;background:#1769aa;color:#fff;padding:12px 18px;font:600 14px system-ui;cursor:pointer}.pw-scroll{overflow:auto}.pw-scroll table{width:100%;border-collapse:collapse}.pw-scroll th,.pw-scroll td{padding:10px;border-bottom:1px solid #e2e9f0;text-align:left;font-size:12px}.pw details{margin:15px 0;padding:15px;border:1px solid #e2e9f0;border-radius:8px}.pw summary{cursor:pointer;font-weight:600}.pw a:focus-visible,.pw button:focus-visible,.pw input:focus-visible,.pw select:focus-visible,.pw textarea:focus-visible,.pw summary:focus-visible{outline:3px solid #e5ab45;outline-offset:3px}@media(max-width:1100px){.pw-kpis{grid-template-columns:1fr 1fr}}@media(max-width:760px){.pw-grid{grid-template-columns:1fr}}@media(max-width:450px){.pw-kpis{grid-template-columns:1fr}.pw-panel dl{grid-template-columns:1fr}}</style>';}
}
